inline const char* Creature(int id) {
    if (id < 0 || id > kCreatureMax) return "?";
    for (const auto& e : kCreatures) if (e.id == id) return e.name;
    return "?";
}

inline const char* Spell(int id) {
    if (id < 0 || id > kSpellMax) return "?";
    for (const auto& e : kSpells) if (e.id == id) return e.name;
    return "?";
}

